/**
 * The Google Fonts catalogue (every family with a latin subset, most popular first), generated by
 * `npm run fonts:sync`. Pure: safe on the server and in the browser.
 */
import catalog from './google-fonts.json'

export type FontCategory = 'sans' | 'serif' | 'display' | 'handwriting' | 'mono'

export interface GoogleFont {
  name: string
  category: FontCategory
  /** Upright weights, ascending; the italic ones when italicOnly. */
  weights: readonly number[]
  /** The family has italic styles only (e.g. Molle). */
  italicOnly?: boolean
}

const CATEGORY: Record<string, FontCategory> = { s: 'sans', r: 'serif', d: 'display', h: 'handwriting', m: 'mono' }

type Tuple = [name: string, category: string, weights: number[], italicOnly?: number]

export const GOOGLE_FONTS: readonly GoogleFont[] = (catalog as Tuple[]).map(([name, code, weights, italic]) => ({
  name,
  category: CATEGORY[code] ?? 'sans',
  weights,
  ...(italic ? { italicOnly: true } : {}),
}))

const BY_NAME: ReadonlyMap<string, GoogleFont> = new Map(GOOGLE_FONTS.map((font) => [font.name, font]))

/** Own keys only: a Map never answers '__proto__' or 'constructor'. */
export function googleFontOf(name: string): GoogleFont | undefined {
  return BY_NAME.get(name)
}

export const isGoogleFont = (value: unknown): value is string => typeof value === 'string' && BY_NAME.has(value)

/** Case-insensitive; names starting with the query come before names merely containing it, each in popularity order. */
export function searchFonts(query: string, opts: { category?: FontCategory; limit?: number } = {}): GoogleFont[] {
  const q = query.trim().toLowerCase()
  const limit = opts.limit ?? Infinity
  const prefix: GoogleFont[] = []
  const inner: GoogleFont[] = []
  for (const font of GOOGLE_FONTS) {
    if (opts.category && font.category !== opts.category) continue
    const name = font.name.toLowerCase()
    if (!q || name.startsWith(q)) prefix.push(font)
    else if (name.includes(q)) inner.push(font)
    if (prefix.length >= limit) break
  }
  return [...prefix, ...inner].slice(0, limit)
}

const GENERIC: Record<FontCategory, string> = {
  sans: 'sans-serif',
  serif: 'serif',
  display: 'sans-serif',
  handwriting: 'cursive',
  mono: 'monospace',
}

/** A CSS font-family value for a catalogue font, with a generic fallback by its category. */
export function cssFamily(name: string): string {
  const generic = GENERIC[googleFontOf(name)?.category ?? 'sans']
  return `'${name.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}', ${generic}`
}
